if(!exists('survival_backtest',mode='function'))library(creditratingsystem)
close<-function(a,b,tol=1e-12)stopifnot(max(abs(unlist(a)-unlist(b)))<tol)
d<-list(model_id='survival',model_version='1',parameter_version='1',data_fingerprint='synthetic-times',population_id='performing',split_id='holdout',prediction_origin='HOLDOUT',evaluation_cutoff='2020-01-10',days_per_time_unit=1,target=list(event='default',horizon=2,time_unit='days',probability_measure='PHYSICAL',conditioning='performing'));rows<-lapply(0:3,function(i)list(prediction_id=as.character(i),entity_id=paste0('e',i),cluster_id=paste0('g',i),segment='all',as_of='2020-01-01',forecast_known_at='2020-01-01',horizon_end='2020-01-03',model_id='survival',model_version='1',parameter_version='1',outcome_known_at='2020-01-05',observed_time=c(1,3,3,3)[i+1],event=c(TRUE,TRUE,FALSE,FALSE)[i+1]));p<-rbind(c(.7,.8),c(.1,.2),c(.1,.3),c(.2,.4));complete<-list(method='complete_followup',reference='complete observed sample');r<-survival_backtest(p,rows,c(1,2),complete,d,'none')$value;close(vapply(r$metrics$by_horizon,function(v)v$brier,numeric(1)),c(.0375,.0825));close(r$metrics$integrated_brier,.06);stopifnot(r$metrics$concordance$value==1);close(r$metrics$by_horizon[[2]]$brier,brier_score(c(1,0,0,0),p[,2])$value$brier)
rows[[3]]$observed_time<-2;censoring<-list(method='frozen_ipcw',reference='known censor distribution',independence_assumption='censoring_independent_of_event_features_and_across_clusters',tie_rule='event_before_censoring',model_fingerprint='synthetic-G',model_known_at='2019-01-01',times=list(1),survival=list(.5),support_end=3,minimum_survival=.1);r<-survival_backtest(p,rows,c(1,2),censoring,d,'none')$value;close(vapply(r$metrics$by_horizon,function(v)v$brier,numeric(1)),c(.0525,.11));close(r$metrics$concordance$pair_mass,6);stopifnot(r$metrics$by_horizon[[2]]$censored_by_horizon==1)
p[2,]<-c(.7,.8);rows[[4]]$cluster_id<-'g0';r<-survival_backtest(p,rows,c(1,2),censoring,d,'none')$value;close(r$metrics$by_horizon[[1]]$auc,.75);close(r$metrics$concordance$value,.75);censoring$survival<-list(0);r<-survival_backtest(p,rows,c(1,2),censoring,d,'none')$value;stopifnot(r$applicability=='NOT_APPLICABLE',all(vapply(r$metrics$by_horizon,function(v)is.null(v$brier),logical(1))))
rows[[3]]$observed_time<-3;rows[[4]]$cluster_id<-'g3';r<-survival_backtest(p,rows,c(1,2),complete,d,'cluster_bootstrap',list(rep('g0',4),c('g1','g2','g3','g3')))$value;stopifnot(r$uncertainty$intervals$auc_0$reason=='NON_ESTIMABLE_RESAMPLE',!is.null(r$uncertainty$intervals$brier_0$lower))
stopifnot(survival_backtest(list(),list(),c(1,2),complete,d,'none')$value$applicability=='NOT_APPLICABLE')
